// Yggdrasil spatial index behind Hydra's NearestNodeFinder, which the frontend and backend use
// for every nearest-node search (attaching objects to places, connecting places, frontiers,
// merge candidates). Needs patches/hydra/0003; selected with HYDRA_NN_BACKEND=yggdrasil|both.
#include <hydra/utils/nearest_neighbor_utilities.h>

#include <cmath>

#include "ygg_bridge_cxx/lib.h"  // generated by corrosion_add_cxxbridge

namespace hydra_ygg {
namespace {

class YggdrasilNnBackend : public hydra::NearestNodeBackend {
 public:
  explicit YggdrasilNnBackend(const std::vector<Eigen::Vector3d>& points)
      : index_(new_node_index()) {
    for (size_t i = 0; i < points.size(); ++i) {
      index_->add(0, i, points[i].x(), points[i].y(), points[i].z());
    }
  }

  std::vector<Result> knn(const Eigen::Vector3d& p, size_t count) const override {
    return convert(index_->nearest_n(0, p.x(), p.y(), p.z(), count));
  }

  std::vector<Result> radius(const Eigen::Vector3d& p, double radius) const override {
    // nanoflann's (and so Hydra's) radius is a squared distance
    return convert(index_->within(0, p.x(), p.y(), p.z(), std::sqrt(radius)));
  }

 private:
  static std::vector<Result> convert(const rust::Vec<Neighbor>& found) {
    std::vector<Result> results;
    results.reserve(found.size());
    for (const auto& n : found) {
      results.push_back({static_cast<size_t>(n.id), n.distance * n.distance});
    }
    return results;
  }

  rust::Box<NodeIndex> index_;
};

const bool registered = [] {
  hydra::NearestNodeBackend::factory() = [](const std::vector<Eigen::Vector3d>& points) {
    return hydra::NearestNodeBackend::Ptr(new YggdrasilNnBackend(points));
  };
  return true;
}();

}  // namespace
}  // namespace hydra_ygg
